export const modules: Module[] = [
  cpuOverview,
  cpuPch,
  testEnvOverview,
  remoteConnection,
  biosOverview,
  postCodePort80,
  ttkTools,
  powerSplitter,
  targetDevices,
  typeCTcss,
  debugConnection,
  osbvSvos,
  thermalBasics,
];

export function getModule(id: string): Module | undefined {
  return modules.find((m) => m.id === id);
}

export const availableModules = modules.filter((m) => m.available);
